/// This app's parsing, against the server's ACTUAL responses.
///
/// `test/contracts/auth_contracts.json` is not written by hand. It is
/// generated by `tests/test_auth_contract_capture.py` in the backend, from
/// real responses produced by the real views, and copied here. If a view's
/// shape changes, that file changes and these tests fail — and nobody can
/// "fix" them by editing a fixture to match the app.
///
/// The driver app shipped a defect this approach is designed to catch: it
/// read `data['access']` while the server sends `token`, so login could never
/// succeed, and its own hand-written fixtures hid it because they used the
/// same wrong key.
///
/// Regenerate: run the backend test, then
///   cp contracts/auth_contracts.json ../SaaradhiGo-mobile/test/contracts/
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:saaradhigo_rider/services/api_service.dart';
import 'package:shared_preferences/shared_preferences.dart';

Map<String, dynamic> _loadContract() {
  final file = File('test/contracts/auth_contracts.json');
  if (!file.existsSync()) {
    fail(
      'test/contracts/auth_contracts.json is missing. Generate it by running '
      'the backend test tests/test_auth_contract_capture.py and copying '
      'contracts/auth_contracts.json here.',
    );
  }
  return jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
}

Map<String, dynamic> _endpoint(String name) {
  final endpoints = _loadContract()['endpoints'] as Map<String, dynamic>;
  final entry = endpoints[name];
  if (entry == null) {
    fail('The contract has no entry "$name". Captured: '
        '${endpoints.keys.join(", ")}');
  }
  return entry as Map<String, dynamic>;
}

/// A client that replays one captured response.
http.Client _replaying(String name) {
  final entry = _endpoint(name);
  return MockClient((_) async => http.Response(
        jsonEncode(entry['body']),
        entry['status_code'] as int,
        headers: {'content-type': 'application/json'},
      ));
}

void main() {
  // TokenStore writes through flutter_secure_storage and SharedPreferences,
  // both platform channels, so the binding has to exist before any of this
  // runs.
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() {
    SharedPreferences.setMockInitialValues({});
  });

  group('the contract file itself', () {
    test('exists and names the generator', () {
      expect(_loadContract()['_README'], contains('GENERATED'));
    });

    test('the access token key is `token`, not `access`', () {
      final data = ((_endpoint('auth_login_otp')['body'] as Map)['data'] as Map)
          .cast<String, dynamic>();

      expect(data.containsKey('token'), isTrue);
      expect(data.containsKey('refresh_token'), isTrue);
      expect(data.containsKey('access'), isFalse,
          reason: 'the driver app read `access` here and could never log in');
    });

    test('the OTP and email logins have the SAME envelope', () {
      final otp = ((_endpoint('auth_login_otp')['body'] as Map)['data'] as Map)
          .keys
          .toSet();
      final email =
          ((_endpoint('auth_login_email')['body'] as Map)['data'] as Map)
              .keys
              .toSet();
      expect(email, otp);
    });
  });

  group('mobile OTP login', () {
    test('this app stores the token from the real response', () async {
      final api = ApiService(client: _replaying('auth_login_otp'));

      final result = await api.verifyOtpAndLogin('+919999000001', '100001', '');

      expect(result, isNotNull);
      final expected =
          ((_endpoint('auth_login_otp')['body'] as Map)['data'] as Map)
              .cast<String, dynamic>();
      final prefs = await SharedPreferences.getInstance();
      expect(prefs.getString('access_token'), expected['token']);
      expect(prefs.getString('refresh_token'), expected['refresh_token']);
    });
  });

  group('email + password login', () {
    test('this app stores the token from the real response', () async {
      final api = ApiService(client: _replaying('auth_login_email'));

      final result = await api.emailLogin(
        email: 'contract-rider@example.test',
        password: 'Cadence-Harbour-74',
      );

      expect(result, isNotNull);
      expect(result!.containsKey('_error'), isFalse);

      final expected =
          ((_endpoint('auth_login_email')['body'] as Map)['data'] as Map)
              .cast<String, dynamic>();
      final prefs = await SharedPreferences.getInstance();
      expect(prefs.getString('access_token'), expected['token']);
    });

    test('a rejected login is reported as an error, not a session', () async {
      final api = ApiService(client: _replaying('auth_login_email_rejected'));

      final result = await api.emailLogin(
        email: 'contract-rider@example.test',
        password: 'wrong',
      );

      expect(result, isNotNull);
      expect(result!['_error'], isNotNull);
      expect((result['_error'] as Map)['code'], 'AUTH_INVALID_CREDENTIALS');

      final prefs = await SharedPreferences.getInstance();
      expect(prefs.getString('access_token'), isNull);
    });

    test('an operator MFA challenge is distinguishable from a bad password',
        () async {
      // The ONLY distinction the server makes, and only after the password
      // was accepted -- so the app can show the code field without leaking
      // anything to someone who does not already hold the password.
      final api = ApiService(client: _replaying('auth_login_email_mfa_required'));

      final result = await api.emailLogin(
        email: 'contract-ops@example.test',
        password: 'Cadence-Harbour-74',
      );

      expect((result!['_error'] as Map)['code'], 'AUTH_MFA_REQUIRED');
    });

    test('the refusal carries no hint about which part was wrong', () {
      final error =
          ((_endpoint('auth_login_email_rejected')['body'] as Map)['error']
                  as Map)
              .cast<String, dynamic>();

      expect(error['message'], 'Invalid email or password.');
      final text = jsonEncode(error).toLowerCase();
      for (final leak in ['no account', 'not found', 'unknown', 'no such']) {
        expect(text.contains(leak), isFalse,
            reason: 'the refusal leaks "$leak"');
      }
    });
  });

  group('password reset', () {
    test('this app accepts the real forgot-password response', () async {
      final api = ApiService(client: _replaying('auth_password_forgot'));

      final ok = await api.requestPasswordReset('contract-rider@example.test');

      expect(ok, isTrue);
    });

    test('the response body reveals nothing', () {
      final message = (((_endpoint('auth_password_forgot')['body']
              as Map)['data'] as Map)['message'] as String)
          .toLowerCase();
      expect(message, contains('if that address belongs to an account'));
    });
  });

  group('role-based access', () {
    test('a rider token is refused at an operator endpoint', () {
      expect(_endpoint('auth_rbac_rider_denied_admin')['status_code'],
          anyOf(401, 403));
    });

    test('an anonymous request is refused', () {
      expect(_endpoint('auth_profile_anonymous_denied')['status_code'],
          anyOf(401, 403));
    });
  });
}
